#!/usr/bin/env bash
set -Eeuo pipefail
PROJECT="/scratch/lj2634/Isaac-Go2-Low-Level-RL"; EXP="$PROJECT/experiments/r8_55_touchdown_hold"; PY="/scratch/lj2634/envs/isaaclab232_v2/bin/python"; FREEZE="/scratch/lj2634/runs/go2_soccer_kick_freeze/ballfree_r841_grace6_20260810_185244"
echo '===== R8.55 PREFLIGHT (NO GPU) ====='; bash -n "$EXP/run_r855_hold.sbatch" "$EXP/check_r855_latest.sh"; "$PY" -m py_compile "$EXP/patch_r855_source.py"; echo SCRIPT_SYNTAX=OK
R854_RUN="$(tr -d '\r\n' < /scratch/lj2634/runs/go2_soccer_r8_54_strength_conditioned_recovery/latest_r854.txt)"; R851_RUN="$(tr -d '\r\n' < /scratch/lj2634/runs/go2_soccer_r8_51_kick64_true_contact/latest_r851.txt)"; R850_RUN="$(tr -d '\r\n' < "$PROJECT/experiments/r8_50_real_contact_truth/latest_r850.txt")"; SOURCE="$R854_RUN/train_r854_strength_recovery.py"
for f in "$SOURCE" "$R854_RUN/output/recovery64_final.pt" "$R851_RUN/output/kick64_final.pt" "$R851_RUN/output/r851_summary.json" "$R850_RUN/body_names.json" "$FREEZE/artifacts/r821_lift_base.pt"; do [[ -s "$f" ]] || { echo "PREFLIGHT_FATAL missing: $f" >&2; exit 32; }; stat --printf='READY %n %s bytes\n' "$f"; done
TEMP="$(mktemp -d /scratch/lj2634/r855_preflight_XXXXXX)"; trap 'rm -rf -- "$TEMP"' EXIT; "$PY" "$EXP/patch_r855_source.py" --source "$SOURCE" --output "$TEMP/train_r855.py"; "$PY" -m py_compile "$TEMP/train_r855.py"; grep -q 'def _r855_eval' "$TEMP/train_r855.py"; grep -q 'R855_TOUCHDOWN_HOLD_ONLY' "$TEMP/train_r855.py"; grep -q '^export R855_TOUCHDOWN_HOLD_ONLY=1.*R851_BODY_JSON=' "$EXP/run_r855_hold.sbatch"; echo "R854_RUN=$R854_RUN"; echo "SOURCE_SHA256=$(sha256sum "$SOURCE"|awk '{print $1}')"; echo PATCH_INJECTION=OK; echo BODY_JSON_ALIAS=OK; echo R855_PREFLIGHT_OK
